'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),{spawnSync}=require('node:child_process');
const base=__dirname,out=path.join(base,'업로드_최종_20260926'),audit=path.join(base,'검수/업로드_20260926'),file=path.join(out,'yuhobuilds_EP01_FINAL_1080x1920.mp4');
const framesDir=path.join(audit,'final-frames');fs.mkdirSync(framesDir,{recursive:true});
function run(exe,args){const r=spawnSync(exe,args,{encoding:'utf8',windowsHide:true,maxBuffer:12*1024*1024});if(r.status!==0)throw Error(r.stderr||r.error);return r;}
const sha=f=>crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex');
const read=name=>JSON.parse(fs.readFileSync(path.join(audit,name),'utf8'));
const timing=read('final-timing.json'),captions=read('final-captions.json'),words=read('final-words.json'),script=read('final-script.json'),edit=read('edit-decision.json');
const normalize=s=>s.replaceAll('백 시간','100시간').replaceAll('일인 기업가','1인 기업가').replaceAll('유월','6월').replaceAll('이일','2일').replace(/[\s.,!?]/g,'');
if(normalize(script.segments.map(s=>s.text).join(''))!==normalize(captions.map(c=>c.text).join('')))throw Error('Caption text mismatch');
if(captions.some((c,i)=>c.endMs<=c.startMs||c.endMs>timing.durationInFrames/30*1000||(i&&c.startMs<captions[i-1].endMs)))throw Error('Caption timing mismatch');
let end=0;for(const scene of timing.scenes){if(scene.start!==end)throw Error('Scene gap');end+=scene.duration;}if(end!==timing.durationInFrames)throw Error('End frame mismatch');
if(sha(path.join(base,'yuhobuilds_EP01.mp4'))!==edit.sourceSha256)throw Error('Original master changed');
if(timing.scenes.some(s=>s.id==='15a')||script.segments.some(s=>s.text.includes('다음 편에서는')))throw Error('Obsolete preview survived');
const typed=timing.scenes.find(s=>s.visual==='prompt');const lastWord=words.find(w=>w.segment===typed.id&&w.text==='싶어.');const typingErrorMs=((typed.start+typed.typing.endFrame)/30-lastWord.end)*1000;
if(Math.abs(typingErrorMs)>1000/30)throw Error('Typing sync changed');
const probe=JSON.parse(run('ffprobe',['-v','error','-show_streams','-show_format','-of','json',file]).stdout);
const v=probe.streams.find(s=>s.codec_type==='video'),a=probe.streams.find(s=>s.codec_type==='audio');
if(v.codec_name!=='h264'||v.width!==1080||v.height!==1920||v.pix_fmt!=='yuv420p'||v.r_frame_rate!=='30/1'||Number(v.nb_frames)!==2188||a.codec_name!=='aac'||a.sample_rate!=='48000'||a.channels!==2)throw Error('Output spec mismatch');
const decode=run('ffmpeg',['-v','info','-i',file,'-vf','blackdetect=d=0.08:pix_th=0.08:pic_th=0.98','-af','loudnorm=I=-16:TP=-1.5:LRA=9:print_format=json','-f','null','-']).stderr;
const loudness=JSON.parse(decode.slice(decode.lastIndexOf('{'),decode.lastIndexOf('}')+1));
const black=decode.split('\n').filter(s=>s.includes('black_start:'));
if(black.length||Math.abs(Number(loudness.input_i)+16)>.5||Number(loudness.input_tp)>-1)throw Error('Black or audio level failed');
fs.writeFileSync(path.join(audit,'final-decode.txt'),decode);
const sampleStart=edit.removedScene.startFrame*1600,sampleEnd=(edit.removedScene.startFrame+edit.removedScene.frames)*1600;
const voiceExpected=run('ffmpeg',['-v','error','-i',path.join(base,'audio/narration-only.wav'),'-filter_complex',`[0:a]asplit=2[a][b];[a]atrim=end_sample=${sampleStart},asetpts=PTS-STARTPTS[head];[b]atrim=start_sample=${sampleEnd},asetpts=PTS-STARTPTS[tail];[head][tail]concat=n=2:v=0:a=1[out]`,'-map','[out]','-c:a','pcm_s16le','-f','hash','-hash','sha256','-']).stdout.trim();
const voiceActual=run('ffmpeg',['-v','error','-i',path.join(audit,'narration-only.wav'),'-c:a','pcm_s16le','-f','hash','-hash','sha256','-']).stdout.trim();
if(voiceExpected!==voiceActual)throw Error('Narration PCM changed beyond the single edit');
const joke=timing.scenes.find(s=>s.visual==='joke');
const bright=spawnSync('ffmpeg',['-v','error','-i',file,'-vf',`select=between(n\\,${joke.start+15}\\,${joke.start+joke.duration-5}),crop=882:410:83:162,scale=88:41,format=gray`,'-fps_mode','passthrough','-an','-f','rawvideo','pipe:1'],{windowsHide:true,maxBuffer:4*1024*1024});if(bright.status!==0)throw Error('Heading frame audit failed');
const counts=[];for(let o=0;o<bright.stdout.length;o+=88*41){let n=0;for(const value of bright.stdout.subarray(o,o+88*41))if(value>160)n++;counts.push(n);}if(counts.length!==joke.duration-19||Math.min(...counts)<80)throw Error('Joke heading dropout');
const frames=[0,20,60,105,...timing.scenes.slice(1).map(s=>s.start+Math.round(s.duration*.55)),1130,1175,1388,1755,1768,1990,1993,2000,2047,2062,2063,2075,2150,2187].sort((a,b)=>a-b).filter((n,i,arr)=>!i||arr[i-1]!==n);
run('ffmpeg',['-v','error','-y','-i',file,'-vf',`select=${frames.map(n=>`eq(n\\,${n})`).join('+')},scale=360:640`,'-fps_mode','vfr','-q:v','2',path.join(framesDir,'frame-%03d.jpg')]);
for(let i=0;i<Math.ceil(frames.length/12);i++)run('ffmpeg',['-v','error','-y','-start_number',String(1+i*12),'-i',path.join(framesDir,'frame-%03d.jpg'),'-vf','tile=4x3:nb_frames=12:padding=3:margin=3:color=gray','-frames:v','1','-q:v','2',path.join(framesDir,`contact-${i+1}.jpg`)]);
fs.writeFileSync(path.join(framesDir,'manifest.json'),JSON.stringify(frames.map((n,i)=>({image:`frame-${String(i+1).padStart(3,'0')}.jpg`,frame:n,seconds:n/30})),null,2));
const bytes=fs.readFileSync(file),moov=bytes.indexOf(Buffer.from('moov')),mdat=bytes.indexOf(Buffer.from('mdat'));if(moov<0||moov>mdat)throw Error('Fast start metadata missing');
const report={createdAt:new Date().toISOString(),output:file,sha256:sha(file),bytes:fs.statSync(file).size,durationSeconds:Number(probe.format.duration),timelineSeconds:timing.durationInFrames/30,video:v,audio:a,fullDecodePassed:true,blackIntervals:black,fastStart:true,captionCount:captions.length,captionTextMatches:true,captionBoundsAndOverlapPassed:true,contiguousScenes:true,originalMasterUnchanged:true,narrationPcmMatchesRetainedBlocks:true,typingErrorMs:Math.round(typingErrorMs),jokeHeading:{frames:counts.length,minBrightPixels:Math.min(...counts),passed:true},loudness,extractedFrames:frames.length,visualReviewCompleted:false,browserPlaybackVerified:false,directListeningVerified:false,publicUpload:false};
fs.writeFileSync(path.join(audit,'final-validation.json'),JSON.stringify(report,null,2));
console.log(JSON.stringify({file,sha256:report.sha256,seconds:report.durationSeconds,captions:captions.length,lufs:loudness.input_i,truePeak:loudness.input_tp,frames:frames.length,passed:true}));
